(function () {
	if (window.echarts) {
		return;
	}

	window.echarts = {
		init: function (element) {
			return {
				setOption: function (option) {
					element.dataset.echartsOption = JSON.stringify(option || {});
					element.innerHTML =
						'<div style="padding: 16px; border: 1px dashed var(--border-color); border-radius: 8px; color: var(--text-muted);">' +
						"Roadmap chart placeholder: replace vendored ECharts stub with production bundle." +
						"</div>";
				},
				dispose: function () {},
			};
		},
	};
})();

